/** Says things in the user's language (the built-in's own texts, translated by the language packs). */
export const tFor = (lang) => (key, vars = {}) => (STRINGS[lang]?.[key] ?? key).replace(/\{(\w+)\}/g, (_, k) => String(vars[k] ?? `{${k}}`));

export const CONN = "google-drive-ext.drive";
export const API = "https://www.googleapis.com";
export const FOLDER_MIME = "application/vnd.google-apps.folder";
const FIELDS = "id,name,mimeType,size,md5Checksum,modifiedTime";
/** All of Drive — needed to see the files you add yourself (documents coming back). */
export const SCOPE_FULL = "https://www.googleapis.com/auth/drive";
export const MAX_DOCUMENT_BYTES = 50 * 1024 * 1024;
/** At most this many files come in per run (the rest next time). */
export const PULL_MAX = 25;
/** Google's own documents, as the Office file Zeff's Documents reads. */
export const EXPORTS = {
  "application/vnd.google-apps.document": { mime: "application/vnd.openxmlformats-officedocument.wordprocessingml.document", ext: ".docx" },
  "application/vnd.google-apps.spreadsheet": { mime: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet", ext: ".xlsx" },
  "application/vnd.google-apps.presentation": { mime: "application/vnd.openxmlformats-officedocument.presentationml.presentation", ext: ".pptx" },
};

/** A value in a Drive query ('…' with ' and \ escaped). */
export const q = (v) => `'${String(v).replace(/\\/g, "\\\\").replace(/'/g, "\\'")}'`;
/** A setting as yes/no (the plugin's settings reach a lambda as text). */
export const flag = (context, key, fallback) => (context.secrets[key] === undefined ? fallback : /^(true|1|on)$/.test(String(context.secrets[key])));
export const folderNameOf = (context) => String(context.secrets.folderName ?? "").trim() || "Zeff";
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

/** Every row of a store of this plugin (pages of 500). */
export async function rows(zeff, store) {
  const out = [];
  for (let offset = 0; ; offset += 500) {
    const { rows: page, total } = await zeff.call("store.query", { store: `google-drive-ext.${store}`, limit: 500, offset });
    out.push(...page);
    if (!page.length || out.length >= total) return out;
  }
}

/** One GET with the token: 401 → a fresh token once; 429/5xx and rate limits → tried again a few times. */
async function get(context, url) {
  let refreshed = false;
  for (let attempt = 0; ; attempt++) {
    const { accessToken } = await context.zeff.call("oauth.token", { connection: CONN, force: refreshed });
    let res;
    try {
      res = await fetch(url, { headers: { authorization: `Bearer ${accessToken}` } });
    } catch (e) {
      if (attempt >= 3) throw e;
      await sleep(1000 * 2 ** attempt);
      continue;
    }
    if (res.status === 401 && !refreshed) {
      refreshed = true;
      attempt--;
      continue;
    }
    if (res.ok || (res.status < 500 && res.status !== 429 && res.status !== 403)) return res;
    const text = res.status === 403 ? await res.clone().text() : "";
    const limited = res.status === 429 || res.status >= 500 || /rateLimitExceeded|userRateLimitExceeded|backendError/.test(text);
    if (!limited || attempt >= 3) return res;
    await sleep(Math.min(8000, 1000 * 2 ** attempt));
  }
}

async function problem(res) {
  const body = await res.json().catch(() => ({}));
  const message = body?.error?.message ?? res.statusText ?? String(res.status);
  if (res.status === 403 && body?.error?.errors?.some((e) => e.reason === "accessNotConfigured")) return new Error("The Google Drive API isn't switched on in your Google Cloud project — enable “Google Drive API” there.");
  return new Error(`Google Drive: ${message} (${res.status})`);
}

async function json(res) {
  if (!res.ok) throw await problem(res);
  return await res.json();
}

/** The folder of that name in `parent` (or the Drive root): its id, or "" when there is none. */
export async function findFolder(context, name, parent) {
  const query = `mimeType=${q(FOLDER_MIME)} and name=${q(name)} and trashed=false and ${q(parent ?? "root")} in parents`;
  const found = await json(await get(context, `${API}/drive/v3/files?${new URLSearchParams({ q: query, fields: "files(id,name)", spaces: "drive", pageSize: "10" })}`));
  return found.files?.[0]?.id ?? "";
}

/** Whether a folder is still there (not deleted, not in the bin) — its id can go stale. */
export async function folderExists(context, id) {
  const res = await get(context, `${API}/drive/v3/files/${encodeURIComponent(id)}?fields=id,trashed,mimeType`);
  if (res.status === 404) return false;
  return !(await json(res)).trashed;
}

/** What's in a folder (files and folders; not what's in the bin). */
export async function listFolder(context, folderId) {
  const out = [];
  let pageToken = "";
  do {
    const params = new URLSearchParams({ q: `${q(folderId)} in parents and trashed=false`, fields: `nextPageToken,files(${FIELDS})`, spaces: "drive", pageSize: "200", orderBy: "modifiedTime desc" });
    if (pageToken) params.set("pageToken", pageToken);
    const page = await json(await get(context, `${API}/drive/v3/files?${params}`));
    out.push(...page.files);
    pageToken = page.nextPageToken ?? "";
  } while (pageToken);
  return out;
}

/** A folder's name and its parent (to walk up to My Drive). */
export async function folderInfo(context, id) {
  return await json(await get(context, `${API}/drive/v3/files/${encodeURIComponent(id)}?fields=id,name,parents`));
}
